SELECT m.id, m.park_org_id, m.company_id, m.employee_id, m.apply_time, m.apply_no, m.park_org_id, m.audit_state, m.stock_state, m.need_return, m.return_num_total, m.remark, m.return_num_current, m.receive_num, m.remark, g.goods_name, m.stock_out_time, m.stock_in_time from cus_pro_receive_manager m LEFT JOIN cus_pro_stock_manager s ON m.stock_id = s.id LEFT JOIN cus_pro_goods_manager g ON s.goods_id = g.id
m.deleted = 0
and m.park_org_id=#{query.parkOrgId}
and m.park_org_id in
#{item}
and m.employee_id in
#{item}
and m.employee_id = #{query.employeeId}
and m.audit_state = #{query.auditState}
and m.stock_state = #{query.stockState}
and m.need_return = #{query.needReturn}
and goods_name like concat('%',#{query.goodsName},'%')
and m.apply_time between #{query.applyTimeStart} and #{query.applyTimeEnd}
order by m.apply_time desc

